import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FileService } from '../../core/services/file.service';
import { OrderByDatePipe } from 'src/app/core/order-by-date.pipe';

@Component({
  selector: 'app-student-files',
  standalone: true,
  imports: [CommonModule, OrderByDatePipe],
  templateUrl: './student-files.component.html',
  styleUrls: ['./student-files.component.scss']
})
export class StudentFilesComponent implements OnInit {
  files: any[] = [];
  filteredFiles: any[] = [];
  loading = true;
  selectedType = 'Cours';

  resourceTypes = [
    { label: 'Cours', icon: '📘' },
    { label: 'TD', icon: '🧩' },
    { label: 'TP', icon: '🧪' },
    { label: 'Autre', icon: '📄' }
  ];

  constructor(private fileService: FileService) {}

  ngOnInit() {
    this.fileService.getFilesByClass(2).subscribe({
      next: (data) => {
        this.files = data;
        this.filterFiles();
        this.loading = false;
      },
      error: (err) => {
        console.error(err);
        this.loading = false;
      }
    });
  }

  /** 🧩 Met à jour la liste filtrée */
  filterFiles() {
    this.filteredFiles = this.files.filter(
      (f) => this.getTypeLabel(f.type) === this.selectedType
    );
  }

  /** 🧮 Compte les fichiers par type */
  getCount(type: string): number {
    return this.files.filter((f) => this.getTypeLabel(f.type) === type).length;
  }

  /** 🔠 Convertit le type en texte */
  getTypeLabel(type: any): string {
    if (typeof type === 'number') {
      switch (type) {
        case 0:
          return 'Cours';
        case 1:
          return 'TD';
        case 2:
          return 'TP';
        case 3:
          return 'Autre';
      }
    } else if (typeof type === 'string') {
      switch (type.toLowerCase()) {
        case 'cours':
          return 'Cours';
        case 'td':
          return 'TD';
        case 'tp':
          return 'TP';
        case 'autre':
          return 'Autre';
      }
    }
    return 'Inconnu';
  }

  /** Quand on change de filtre */
  setSelectedType(type: string) {
    this.selectedType = type;
    this.filterFiles();
  }
}
<section class="container py-5">
  <h2 class="fw-bold text-center mb-4">📚 Ressources de la classe</h2>

  <!-- 🔍 FILTRES -->
  <div class="filter-bar text-center mb-4">
    <button
      *ngFor="let type of resourceTypes"
      class="btn me-2 mb-2"
      [ngClass]="{
        'btn-primary': selectedType === type.label && type.label === 'Cours',
        'btn-success': selectedType === type.label && type.label === 'TD',
        'btn-warning': selectedType === type.label && type.label === 'TP',
        'btn-danger': selectedType === type.label && type.label === 'Autre',
        'btn-outline-primary': selectedType !== type.label && type.label === 'Cours',
        'btn-outline-success': selectedType !== type.label && type.label === 'TD',
        'btn-outline-warning': selectedType !== type.label && type.label === 'TP',
        'btn-outline-danger': selectedType !== type.label && type.label === 'Autre'
      }"
      (click)="selectedType = type.label"
    >
      {{ type.icon }} {{ type.label }}
      <span class="badge bg-light text-dark ms-1">{{ getCount(type.label) }}</span>
    </button>
  </div>

  <!-- 🔄 Loader -->
  <div *ngIf="loading" class="text-center my-5">
    <div class="spinner-border text-primary"></div>
  </div>

  <!-- 🧾 Fichiers -->
  <div *ngIf="!loading && filteredFiles.length > 0; else noFiles">
    <div class="files-grid">
      <div class="file-card shadow-sm" *ngFor="let f of filteredFiles | orderByDate">
        <div class="file-type" [ngClass]="getTypeLabel(f.type).toLowerCase()">
          {{ getTypeLabel(f.type) }}
        </div>

        <h5 class="file-title">{{ f.title }}</h5>

        <p class="file-date text-muted small mb-2">
          <i class="bi bi-calendar-event me-1"></i>
          Ajouté le {{ f.createdAt | date:'dd MMM yyyy, HH:mm' }}
        </p>

        <div class="file-actions">
          <a [href]="f.fileUrl" target="_blank" class="btn btn-outline-primary btn-sm w-100">
            <i class="bi bi-download me-1"></i> Télécharger
          </a>
          <button *ngIf="showDelete" class="btn btn-outline-danger btn-sm w-100 mt-2" (click)="delete(f.id)">
            <i class="bi bi-trash me-1"></i> Supprimer
          </button>
        </div>
      </div>
    </div>
  </div>

  <ng-template #noFiles>
    <div class="alert alert-info text-center mt-5">
      📭 Aucune ressource disponible pour ce type.
    </div>
  </ng-template>
</section>
